import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as s}from"./chunks/EN.P9aPnFBv.js";import{_ as o}from"./chunks/OFF.BrU7kQE-.js";import{_ as i,a as r,b as a}from"./chunks/Diabox3.B9uDiRm7.js";import{_ as n,o as l,c,a3 as p}from"./chunks/framework.g9mfNVRQ.js";const z=JSON.parse('{"title":"Abonné Nightscout","description":"","frontmatter":{"source_hash":"247aedba5a","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/install/nightscoutfollower.md","filePath":"fr/install/nightscoutfollower.md"}'),u={name:"fr/install/nightscoutfollower.md"};function d(m,e,h,g,b,v){return l(),c("div",null,[...e[0]||(e[0]=[p('<div class="warning custom-block"><p class="custom-block-title">Anciens certificats Android</p><p>Vous ne pourrez peut-être pas utiliser cette fonction sur les téléphones sous une version d&#39;Android antérieure à 9 s&#39;ils dépendent de certificats expirés (<a href="https://community.letsencrypt.org/t/support-for-android-7-and-older-from-oct-2024/216446" target="_blank" rel="noreferrer">exemple</a>).<br> Il n&#39;existe pas de solution de contournement.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle<br>   Nightscout Follower</p></div><h3 id="nightscout" tabindex="-1">Nightscout <a class="header-anchor" href="#nightscout" aria-label="Permalink to &quot;Nightscout {#nightscout}&quot;">​</a></h3><p>Pour utiliser xDrip avec les données provenant de votre site <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a>, il vous suffit de saisir l&#39;URL de votre site.</p><div class="admonition xdripitem"><p class="admonition-title">URL Abonnés Nightscout</p><p> Adresse Web pour les abonnés</p></div><p>Avec un Nightscout DIY classique, l&#39;URL ressemble à ceci : <code>https://sitename.yourprovider.com</code><br> N&#39;ajoutez pas <code>/api/v1</code><br> Veillez à utiliser <code>https</code> et non <code>http</code></p><p>Si vous utilisez un service hébergé, contactez le fournisseur pour plus d&#39;informations.</p><p>Si votre site Nightscout est <a href="https://nightscout.github.io/nightscout/security/" target="_blank" rel="noreferrer">sécurisé</a>, vous devez ajouter l&#39;API_SECRET ou le jeton d&#39;accès.</p><p><code>https://API_SECRET@sitename.yourprovider.com</code></p><p><code>https://access_token@sitename.yourprovider.com</code></p><div class="admonition xdripitem"><p class="admonition-title">Télécharger les traitements</p></div><p>Vous pouvez aussi télécharger depuis Nightscout les traitements compatibles (glycémies, calibrations, traitements, notes).</p><div class="admonition xdripitem"><p class="admonition-title">Télécharger les traitements <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Télécharger également les traitements de Nightscout comme Abonné</p></div><p>Pour éviter le risque de données en double (important pour AAPS), vous pouvez empêcher xDrip de télécharger les données qu&#39;il a lui-même envoyées vers Nightscout.</p><div class="admonition xdripitem"><p class="admonition-title">Ignorer les éléments de xDrip <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Éviter de télécharger les éléments chargés par xDrip</p></div><p>Si vous constatez des retards importants dans xDrip, vous pouvez définir un délai fixe pour le resynchroniser avec Nightscout. Laissez la valeur par défaut.</p><div class="admonition xdripitem"><p class="admonition-title">Délai pour l&#39;Abonné Nightscout</p><p> 0&gt;</p></div><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>xDrip ne récupère depuis Nightscout qu&#39;un historique limité (24 heures).</p></div><p>Si votre site Nightscout publie l&#39;état des appareils (batterie de l&#39;uploader, batterie de la pompe), xDrip l&#39;affichera dans État du système.</p><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>Les émulateurs Nightscout locaux tels que <a href="https://github.com/j-kaltes/Juggluco" target="_blank" rel="noreferrer">Juggluco</a> sont également pris en charge comme source pour l&#39;abonné.</p></div><br><h3 id="diabox" tabindex="-1">Diabox <a class="header-anchor" href="#diabox" aria-label="Permalink to &quot;Diabox {#diabox}&quot;">​</a></h3><p>Vous pouvez recevoir les données de <a href="https://sirius.thetaphi.de/diabox/" target="_blank" rel="noreferrer">Diabox</a> en activant la diffusion http dans l&#39;application et en faisant de xDrip un abonné local.</p><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>Vous ne pouvez pas utiliser cette fonction si xDrip exécute un <a href="./../use/interapp.html#web-service">service web</a>.</p></div><img src="'+i+'" style="zoom:75%;"><img src="'+r+'" style="zoom:75%;"><p>Une fois cela fait, réglez xDrip en abonné Nightscout (voir ci-dessus) avec l&#39;adresse :</p><p><code>http://localhost:17580</code></p><img src="'+a+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.03" target="_blank" rel="noreferrer"><em>Dernière modification le 6/7/2026</em></a></p>',31)])])}const D=n(u,[["render",d]]);export{z as __pageData,D as default};
